 static Pawn Actor(int id){var p=Empty<Pawn>();p.thingIDNumber=id;p.def=Empty<ThingDef>();p.def.defName="Human";return p;}
 static int Main(string[] args){AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{string n=new AssemblyName(e.Name).Name;string p=n=="ElementalHearts"?args[1]:n=="0Harmony"?args[2]:Path.Combine(args[0],n+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};try{typeof(WaterAbilitiesRegression).GetMethod("Run",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
 static List<MethodBase> Calls(MethodInfo method){var ops=typeof(OpCodes).GetFields(BindingFlags.Static|BindingFlags.Public).Where(f=>f.FieldType==typeof(OpCode)).Select(f=>(OpCode)f.GetValue(null)).ToDictionary(o=>(ushort)o.Value);var il=method.GetMethodBody().GetILAsByteArray();var found=new List<MethodBase>();for(int i=0;i<il.Length;){ushort c=il[i++];if(c==254)c=(ushort)(0xfe00|il[i++]);var op=ops[c];switch(op.OperandType){case OperandType.InlineMethod:found.Add(method.Module.ResolveMethod(BitConverter.ToInt32(il,i)));i+=4;break;case OperandType.InlineSwitch:int n=BitConverter.ToInt32(il,i);i+=4+4*n;break;case OperandType.InlineNone:break;case OperandType.ShortInlineBrTarget:case OperandType.ShortInlineI:case OperandType.ShortInlineVar:i++;break;case OperandType.InlineVar:i+=2;break;case OperandType.InlineI8:case OperandType.InlineR:i+=8;break;default:i+=4;break;}}return found;}
 static void Run(){
  Check(WaterAbilityRules.CounterLive(220,100,0)&&!WaterAbilityRules.CounterLive(221,100,0)&&WaterAbilityRules.CounterLive(500,100,500)&&!WaterAbilityRules.CounterLive(501,100,500),"Legacy/new pending counter expiry boundary");
  var ids=new HashSet<int>();for(int i=0;i<16;i++)Check(WaterAbilityRules.Commit(ids,i,16),"Unique victim not committed");for(int i=0;i<16;i++)Check(!WaterAbilityRules.Commit(ids,i,16),"Repeat victim committed");Check(!WaterAbilityRules.Commit(ids,999,16)&&ids.Count==16,"Victim budget exceeded");
  foreach(int duration in new[]{16,24,28,32}){var frames=new HashSet<int>();for(int tick=0;tick<duration;tick++)frames.Add(WaterAbilityRules.Frame(tick,duration));Check(frames.Count==8&&frames.Contains(0)&&frames.Contains(7),"Sequence omits frames");}Check(WaterAbilityRules.Frame(-1,24)==0&&WaterAbilityRules.Frame(999,0)==7,"Frame boundary error");
  var valid=new[]{true,true,true,true};int phase=0;for(int p=0;p<4;p++){int choice=WaterAbilityRules.Choose(phase,p,1,valid);Check(choice==p,"Single-target combo does not rotate Torrent -> Step -> Whirlpool -> Judgement");valid[choice]=false;phase=(choice+1)%4;}Check(WaterAbilityRules.Choose(phase,0,1,valid)==-1,"Cooldown-gated combo spams an unavailable skill");Check(WaterAbilityRules.Choose(0,3,1,new[]{true,true,true,true})==3,"Full Pressure does not prioritize finisher");Check(WaterAbilityRules.Choose(0,0,2,new[]{true,true,true,true})==2,"Crowd does not prioritize spin");Check(WaterAbilityRules.Choose(1,1,1,new[]{true,false,false,true})==3,"Unavailable movement/spin not skipped");
  foreach(float d in new[]{0,1,4,6,100}){int time=WaterAbilityRules.StepDuration(d);Check(time>=6&&time<=12,"Step duration unbounded");float prior=0;for(int tick=0;tick<=time;tick++){float current=WaterAbilityRules.StepProgress(tick,time);Check(current>=prior&&current>=0&&current<=1,"Step does not move continuously forward");prior=current;}Check(prior==1,"Step fails to reach landing");}Check(WaterAbilityRules.Cooldown(WaterPower.Torrent)==300&&WaterAbilityRules.Cooldown(WaterPower.Step)==450&&WaterAbilityRules.Cooldown(WaterPower.Whirlpool)==750&&WaterAbilityRules.Cooldown(WaterPower.Judgement)==1800&&WaterAbilityRules.Warmup(WaterPower.Judgement)==24,"Unexpected Water timing");Check(WaterAbilityRules.Damage(WaterPower.Judgement,100)==12.25f,"Pressure bonus exceeds three-stack budget");
  Console.WriteLine("PASS: bounded/deduplicated one-hit commitments, complete eight-frame timing, single-target combo rotation, crowd/full-Pressure priorities, cooldown fallback and eased movement endpoints.");
  var sources=new List<Pawn>();for(int i=0;i<12;i++)sources.Add(Actor(100+i));var pressureRoot=new HediffWithComps{def=new HediffDef{maxSeverity=3},comps=new List<HediffComp>()};var pressure=new HediffComp_WaterPressure{parent=pressureRoot,props=new HediffCompProperties_WaterPressure()};pressureRoot.comps.Add(pressure);
  pressure.Add(sources[0],0);pressure.Add(sources[0],1);pressure.Add(sources[0],2);pressure.Add(sources[0],3);pressure.Add(sources[1],100);Check(pressure.Stacks(sources[0],200)==3&&pressure.Stacks(sources[1],200)==1&&pressureRoot.Severity==3,"Pressure per-owner cap or strongest-only severity");Check(pressure.Consume(sources[0],200)==3&&pressure.Stacks(sources[1],200)==1&&pressureRoot.Severity==1,"Consuming one caster removes another caster's stacks");Check(pressure.Stacks(sources[1],580)==0,"Pressure expires late at its boundary");pressure.Expire(580);Check(pressure.entries.Count==0,"Expired marks retained");for(int i=0;i<sources.Count;i++){pressure.Add(sources[i],1000+i);Check(pressure.entries.Count<=8&&pressureRoot.Severity<=3,"Pressure owner/slow budget exceeded");}Check(pressure.Stacks(sources[0],1020)==0&&pressure.Stacks(sources[11],1020)==1,"Oldest-owner eviction invalid");
  Console.WriteLine("PASS: owner-specific Pressure, three stacks/eight-second expiry, strongest-only slow, isolated consumption and eight-owner cap.");
  var pawn=Actor(1);pawn.jobs=Empty<Pawn_JobTracker>();pawn.health=Empty<Pawn_HealthTracker>();pawn.health.hediffSet=Empty<HediffSet>();pawn.health.hediffSet.hediffs=new List<Hediff>();var root=new HediffWithComps{def=new HediffDef{defName=WaterKitUpgrade.DefName},pawn=pawn,comps=new List<HediffComp>()};pawn.health.hediffSet.hediffs.Add(root);var defense=new HediffComp_WaterDefense{parent=root,props=new HediffCompProperties_WaterDefense(),autoCombat=false,nonLethal=true,readyAt=777};root.comps.Add(defense);var list=root.comps;var destination=new HediffDef{defName=WaterKitUpgrade.DefName,comps=new List<HediffCompProperties>{new HediffCompProperties_ElementalAscension(),new HediffCompProperties_ElementalTransform(),new HediffCompProperties_WaterDefense(),new HediffCompProperties_LightningRecovery(),new HediffCompProperties_WaterAbilities()}};Check(WaterKitUpgrade.Ensure(root,destination),"New powers not added to old Water root");var ability=root.TryGetComp<HediffComp_WaterAbilities>();ability.readyAt[0]=300;ability.readyAt[3]=1800;ability.comboStep=2;ability.comboUntil=5000;var ready=ability.readyAt;Check(!WaterKitUpgrade.Ensure(root,destination)&&root.comps==list&&root.TryGetComp<HediffComp_WaterDefense>()==defense&&!defense.autoCombat&&defense.nonLethal&&defense.readyAt==777&&ability.readyAt==ready&&ready[3]==1800,"Upgrade resets shared mode, defense or active cooldowns");
  var job=new Job{def=new JobDef{defName=WaterTechnique.JobName},count=(int)WaterPower.Step,targetB=new IntVec3(16,0,10)};pawn.jobs.curJob=job;var driver=new JobDriver_WaterTechnique{pawn=pawn,job=job};Set(pawn.jobs,"curDriver",driver);Set(driver,"start",new IntVec3(10,0,10));Set(driver,"initialized",true);Set(driver,"duration",10);Set(driver,"elapsed",5);Check(driver.VisualAt(0).x==10.5f&&driver.VisualAt(5).x==13.5f&&driver.VisualAt(10).x==16.5f,"Native Water step draw positions wrong");Check(WaterTechnique.Busy(pawn)&&ElementalAnimationBridge.Controlled(pawn),"Technique does not own skill gate");var toils=new List<Toil>((IEnumerable<Toil>)typeof(JobDriver_WaterTechnique).GetMethod("MakeNewToils",F).Invoke(driver,null));Check(toils.Count==1&&toils[0].defaultCompleteMode==ToilCompleteMode.Never&&toils[0].handlingFacing&&toils[0].initAction!=null&&toils[0].tickAction!=null,"Native held technique structure missing");job.def.defName="Wait_Combat";Check(!WaterTechnique.Busy(pawn)&&!ElementalAnimationBridge.Controlled(pawn),"Technique gate remains after replacement job");
  var hit=Calls(typeof(JobDriver_WaterTechnique).GetMethod("Hit",F));Check(hit.FindIndex(m=>m.DeclaringType==typeof(WaterAbilityRules)&&m.Name=="Commit")<hit.FindIndex(m=>m.DeclaringType==typeof(WaterCombat)&&m.Name=="Strike"),"Victim commitment occurs after damage");var strike=Calls(typeof(WaterCombat).GetMethod("Strike"));int parry=strike.FindIndex(m=>m.DeclaringType==typeof(WaterDefense)&&m.Name=="TryParry"),nonlethal=strike.FindIndex(m=>m.DeclaringType==typeof(ElementalNonLethal)&&m.Name=="TryApply"),take=strike.FindIndex(m=>m.Name=="TakeDamage");Check(parry>=0&&nonlethal>parry&&take>nonlethal&&strike.Count(m=>m.Name=="TakeDamage")==1,"Pressure strike bypasses parry/non-lethal or uses multiple damage packets");Check(ElementalBalance.Affected("EH_WaterDamage",false,false),"Water damage misses shared balance");
  Console.WriteLine("PASS: repeat-safe addition preserves shared defense/mode/cooldowns, native held movement/gate cleanup, commitment before a single damage packet, parry/non-lethal ordering and shared balance.");
  var fx=new MapComponent_WaterAbilityVfx(null);for(int i=0;i<10000;i++)fx.Add(i%5,Vector3.zero,Vector3.one,i,24,1);Check(((Array)Get(fx,"effects")).Length==128&&((Array)Get(fx,"echoes")).Length==32&&(int)Get(fx,"effectCursor")==10000%128,"Effects grow beyond ring buffer");fx.Add(4,Vector3.zero,Vector3.one,100,24,1,null,null,18);var slot=((int)Get(fx,"effectCursor")+127)%128;var entry=((Array)Get(fx,"effects")).GetValue(slot);Check((int)entry.GetType().GetField("tick").GetValue(entry)==82&&WaterAbilityRules.Frame(100-82,24)==6,"Loaded warning restarts its frames");
  Set(driver,"committed",true);Set(driver,"snapshotReady",true);Set(driver,"damage",44f);Set(driver,"struck",new HashSet<int>{101,102});Set(driver,"impactCell",new IntVec3(17,0,10));var payload=new WaterAbilitySaveCase{ability=ability,driver=driver,job=job,pressure=pressure,refs=sources.Select(p=>new WaterAbilityRefStub{loadID=p.GetUniqueLoadID()}).ToList()};string file=Path.Combine(Path.GetTempPath(),"WaterAbilities_"+Guid.NewGuid().ToString("N")+".xml");Scribe.saver.InitSaving(file,"WaterAbilitiesTest");Scribe_Deep.Look(ref payload,"state");Scribe.saver.FinalizeSaving();var xml=new System.Xml.XmlDocument();xml.Load(file);Check(xml.SelectNodes("WaterAbilitiesTest/state/EH_waterAbilityReadyAt/li").Count==4&&xml.SelectSingleNode("WaterAbilitiesTest/state/EH_waterComboStep").InnerText=="2"&&xml.SelectSingleNode("WaterAbilitiesTest/state/driver/EH_waterTechniqueCommitted").InnerText=="True"&&xml.SelectNodes("WaterAbilitiesTest/state/driver/EH_waterTechniqueVictims/li").Count==2&&xml.SelectNodes("WaterAbilitiesTest/state/EH_waterPressureOwners/li").Count==8,"Native save loses cooldown/combo/impact/Pressure owner state");Check(xml.SelectSingleNode("WaterAbilitiesTest/state/job/targetB").InnerText.Contains("16"),"Native job save loses step landing");File.Delete(file);
  Console.WriteLine("PASS: 10,000 effects stay within 128/32 slots, resumed frame offsets, and native Scribe output for cooldowns/combos, movement, hit IDs, snapshots and Pressure owners.");Console.WriteLine("LIMIT: native loading, live damage/control/combo execution and GPU placement remain in-game checks; reference stubs verify saved IDs only.");
 }
}
public class WaterAbilityRefStub:IExposable,ILoadReferenceable {public string loadID;public string GetUniqueLoadID(){return loadID;}public void ExposeData(){Scribe_Values.Look(ref loadID,"loadID");}}
public class WaterAbilitySaveCase:IExposable {public HediffComp_WaterAbilities ability;public JobDriver_WaterTechnique driver;public Job job;public HediffComp_WaterPressure pressure;public List<WaterAbilityRefStub> refs;public void ExposeData(){Scribe_Collections.Look(ref refs,"sources",LookMode.Deep);ability.CompExposeData();Scribe_Deep.Look(ref driver,"driver");Scribe_Deep.Look(ref job,"job");pressure.CompExposeData();}}
